CREATE SCHEMA IF NOT EXISTS production;
SET search_path TO production,public;
CREATE TABLE IF NOT EXISTS migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, username text UNIQUE NOT NULL, display_name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','designer','operator')), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS machines(id text PRIMARY KEY CHECK(id ~ '^[a-z0-9-]{1,40}$'), name text NOT NULL, fields jsonb NOT NULL, active boolean NOT NULL DEFAULT true);
INSERT INTO machines VALUES ('canon','Canon','["gsm","sides","color","cut"]'),('skycolor','SkyColor','["mirror","color","cut"]'),('laser','Laser','["thickness","mirror","cut"]') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS materials(id text PRIMARY KEY, name text NOT NULL, machine_id text NOT NULL REFERENCES machines(id), unit text NOT NULL CHECK(unit IN ('cm2','m2','piece')), options jsonb NOT NULL DEFAULT '{}', price jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), original_name text NOT NULL, size bigint NOT NULL CHECK(size>0), offset_bytes bigint NOT NULL DEFAULT 0 CHECK(offset_bytes>=0 AND offset_bytes<=size), expected_hash text NOT NULL CHECK(expected_hash ~ '^[a-f0-9]{64}$'), relative_path text UNIQUE NOT NULL, complete boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY, number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, designer_id uuid NOT NULL REFERENCES users(id), operator_id uuid REFERENCES users(id), machine_id text NOT NULL REFERENCES machines(id), customer text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','received','running','completed','archived')), version integer NOT NULL DEFAULT 1, idempotency_key uuid NOT NULL, request_hash text NOT NULL, upload_id uuid UNIQUE NOT NULL REFERENCES uploads(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(designer_id,idempotency_key));
CREATE TABLE IF NOT EXISTS order_items(order_id uuid PRIMARY KEY REFERENCES orders(id), material_id text NOT NULL REFERENCES materials(id), details jsonb NOT NULL, pricing jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS status_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), actor_id uuid NOT NULL REFERENCES users(id), from_status text, to_status text NOT NULL, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS archives(order_id uuid PRIMARY KEY REFERENCES orders(id), relative_path text UNIQUE NOT NULL, sha256 text NOT NULL, archived_by uuid NOT NULL REFERENCES users(id), archived_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(user_id uuid NOT NULL REFERENCES users(id), day date NOT NULL, acknowledged_at timestamptz, snooze_until timestamptz, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, entity_id text, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), version integer NOT NULL, payload jsonb NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,version));
CREATE INDEX IF NOT EXISTS orders_status_created ON orders(status,created_at DESC);
CREATE INDEX IF NOT EXISTS orders_machine_created ON orders(machine_id,created_at DESC);
CREATE INDEX IF NOT EXISTS history_order ON status_history(order_id,at);
CREATE INDEX IF NOT EXISTS pending_outbox ON outbox(id) WHERE delivered_at IS NULL;
INSERT INTO migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
